{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-plugin-litellm-pricing",
  "version": "1.0.0",
  "description": "OpenCode 2 plugin: dynamic LiteLLM model discovery with real per-model pricing, read from the proxy's own /v1/model/info",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src/",
    "README.md"
  ],
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsc --noEmit",
    "test": "tsc --noEmit && node --test test/*.test.ts"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "litellm",
    "plugin",
    "llm-proxy",
    "openai-compatible",
    "pricing",
    "cost"
  ],
  "author": "trick77 (https://github.com/trick77)",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/trick77/opencode-plugin-litellm-pricing.git"
  },
  "homepage": "https://github.com/trick77/opencode-plugin-litellm-pricing#readme",
  "bugs": {
    "url": "https://github.com/trick77/opencode-plugin-litellm-pricing/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.5",
    "@types/node": "26.6.6",
    "typescript": "7.0.2"
  }
}
